19	import { QueryFormData } from '@superset-ui/core';
20	import buildQuery from './buildQuery';
21	
22	jest.mock('@superset-ui/core', () => ({
23	  ...jest.requireActual('@superset-ui/core'),
24	  getXAxisColumn: jest.fn(() => 'order_date'),
25	  isXAxisSet: jest.fn(() => true),
26	}));
27	
28	jest.mock('@superset-ui/chart-controls', () => ({
29	  pivotOperator: jest.fn(() => ({ operation: 'pivot' })),
30	  aggregationOperator: jest.fn(formData => {
31	    if (formData.aggregation === 'LAST_VALUE' || !formData.aggregation) {
32	      return undefined;
33	    }
34	    return {
35	      operation: 'aggregation',
36	      options: { operator: formData.aggregation },
37	    };
38	  }),
39	  flattenOperator: jest.fn(() => ({ operation: 'flatten' })),
40	  resampleOperator: jest.fn(() => ({ operation: 'resample' })),
41	  rollingWindowOperator: jest.fn(() => ({ operation: 'rolling' })),
42	}));
43	
44	describe('BigNumberWithTrendline buildQuery', () => {
45	  const baseFormData: QueryFormData = {
46	    datasource: '1__table',
47	    viz_type: 'big_number',
48	    metric: 'custom_metric',
49	    aggregation: null,
50	  };
51	
52	  it('creates raw metric query when aggregation is null', () => {
53	    const queryContext = buildQuery({ ...baseFormData });
54	    const bigNumberQuery = queryContext.queries[1];
55	
56	    expect(bigNumberQuery.post_processing).toEqual([{ operation: 'pivot' }]);
57	    expect(bigNumberQuery.is_timeseries).toBe(true);
58	  });
59	
60	  it('adds aggregation operator when aggregation is "sum"', () => {
61	    const queryContext = buildQuery({ ...baseFormData, aggregation: 'sum' });
62	    const bigNumberQuery = queryContext.queries[1];
63	
64	    expect(bigNumberQuery.post_processing).toEqual([
65	      { operation: 'pivot' },
66	      { operation: 'aggregation', options: { operator: 'sum' } },
67	    ]);
68	    expect(bigNumberQuery.is_timeseries).toBe(true);
69	  });
70	
71	  it('skips aggregation when aggregation is LAST_VALUE', () => {
72	    const queryContext = buildQuery({
73	      ...baseFormData,
74	      aggregation: 'LAST_VALUE',
75	    });
76	    const bigNumberQuery = queryContext.queries[1];
77	
78	    expect(bigNumberQuery.post_processing).toEqual([{ operation: 'pivot' }]);
79	    expect(bigNumberQuery.is_timeseries).toBe(true);
80	  });
81	
82	  it('always returns two queries', () => {
83	    const queryContext = buildQuery({ ...baseFormData });
84	    expect(queryContext.queries.length).toBe(2);
85	  });
86	});
