export default function buildQuery(formData: QueryFormData) {
  const isRawMetric = formData.aggregation === 'raw';

  const timeColumn = isXAxisSet(formData)
    ? ensureIsArray(getXAxisColumn(formData))
    : [];

  return buildQueryContext(formData, baseQueryObject => {
    // The trendline query returns the full series. For every aggregation method
    // except `raw`, the headline number is now derived client-side from this
    // series (see transformProps), so a single query is all that's needed.
    const trendlineQuery = {
      ...baseQueryObject,
      columns: [...timeColumn],
      ...(timeColumn.length ? {} : { is_timeseries: true }),
      post_processing: [
        pivotOperator(formData, baseQueryObject),
        rollingWindowOperator(formData, baseQueryObject),
        resampleOperator(formData, baseQueryObject),
        flattenOperator(formData, baseQueryObject),
      ],
    };

    if (!isRawMetric) {
      return [trendlineQuery];
    }

    // `raw` cannot be computed client-side, so keep a dedicated query that
    // returns the raw metric value with no post-processing.
    return [
      trendlineQuery,
      {
        ...baseQueryObject,
        columns: [],
        is_timeseries: false,
        post_processing: [],
      },
    ];
